use acer_device::Device;
use acer_protocol::{backlight_frame_matches,lighting_call_ack,observed_backlight_frame,static_color_restore_plan,static_color_trial_matches,static_color_trial_plan,ApplyReport,ApplyStatus,BacklightFrame,Call,Capabilities,DeviceError,Snapshot,VALIDATION_STATIC_ZONES};
use serde::Serialize;use crate::validation::Outcome;
#[derive(Serialize)]pub struct Report{command:&'static str,target_brightness:u8,target_zones:[[u8;3];4],outcome:Outcome,message:String,capabilities:Option<Capabilities>,original_frame:Option<BacklightFrame>,initial_snapshot:Option<Snapshot>,trial_apply:Option<ApplyReport>,color_snapshot:Option<Snapshot>,color_readback_confirmed:bool,restore_attempted:bool,restore_apply:Option<ApplyReport>,restored_snapshot:Option<Snapshot>,restore_readback_confirmed:bool,errors:Vec<(&'static str,DeviceError)>}
impl Report{
    pub fn success(&self)->bool{self.outcome==Outcome::ReadbacksConfirmed}
    fn new()->Self{Self{command:"--validate-lighting-static-colors-restore",target_brightness:20,target_zones:VALIDATION_STATIC_ZONES,outcome:Outcome::Rejected,message:String::new(),capabilities:None,original_frame:None,initial_snapshot:None,trial_apply:None,color_snapshot:None,color_readback_confirmed:false,restore_attempted:false,restore_apply:None,restored_snapshot:None,restore_readback_confirmed:false,errors:vec![]}}
    fn finish(mut self,message:&str)->Self{self.message=message.into();self}
}
trait ColorDevice{fn capabilities(&mut self)->Result<Capabilities,DeviceError>;fn snapshot(&mut self)->Result<Snapshot,DeviceError>;fn colors(&mut self)->Result<ApplyReport,DeviceError>;fn restore(&mut self)->Result<ApplyReport,DeviceError>;fn settle(&mut self);}
struct Native<'a>(&'a Device);
impl ColorDevice for Native<'_>{fn capabilities(&mut self)->Result<Capabilities,DeviceError>{self.0.capabilities()}fn snapshot(&mut self)->Result<Snapshot,DeviceError>{self.0.snapshot()}fn colors(&mut self)->Result<ApplyReport,DeviceError>{self.0.begin_static_colors_validation()}fn restore(&mut self)->Result<ApplyReport,DeviceError>{self.0.restore_validation_static_colors()}fn settle(&mut self){std::thread::sleep(std::time::Duration::from_secs(2));}}
pub fn run(device:&Device)->Report{validate(&mut Native(device))}
fn accepted(report:&ApplyReport,calls:&[Call])->bool{!matches!(report.status,ApplyStatus::Failed|ApplyStatus::Rejected)&&report.writes.len()==calls.len()&&calls.iter().zip(&report.writes).all(|(c,r)|lighting_call_ack(c,r)==Some(true))}
fn validate(device:&mut impl ColorDevice)->Report{
    let mut report=Report::new();let caps=match device.capabilities(){Ok(c)=>c,Err(e)=>{report.errors.push(("capabilities",e));return report.finish("Cannot verify target; no color write attempted");}};
    let target=caps.matched_model&&acer_device::verified_fan_target(&caps.model,&caps.bios);report.capabilities=Some(caps);if !target{return report.finish("Requires PHN16-71/V1.18; no write attempted");}
    let before=match device.snapshot(){Ok(s)=>s,Err(e)=>{report.errors.push(("initial_read",e));return report.finish("Initial read failed; no color write attempted");}};report.original_frame=observed_backlight_frame(&before);report.initial_snapshot=Some(before);
    if !report.original_frame.as_ref().is_some_and(|f|static_color_restore_plan(f).is_some()){return report.finish("Requires static frame and four safely restorable zone words; no write attempted");}
    let trial_ok=match device.colors(){Ok(r)=>{if let Some(frame)=r.before.as_ref().and_then(observed_backlight_frame){report.original_frame=Some(frame);}let calls=static_color_trial_plan(report.original_frame.as_ref().unwrap()).unwrap();let ok=accepted(&r,&calls);report.trial_apply=Some(r);ok},Err(e)=>{report.errors.push(("color_write",e));false}};
    if trial_ok{device.settle();match device.snapshot(){Ok(s)=>{report.color_readback_confirmed=static_color_trial_matches(&s,report.original_frame.as_ref().unwrap());report.color_snapshot=Some(s);},Err(e)=>report.errors.push(("color_read",e)),}}
    report.restore_attempted=true;let saved=report.original_frame.as_ref().unwrap();let restore_calls=static_color_restore_plan(saved).unwrap();
    let restore_ok=match device.restore(){Ok(r)=>{let ok=accepted(&r,&restore_calls);report.restore_apply=Some(r);ok},Err(e)=>{report.errors.push(("restore_write",e));false}};
    match device.snapshot(){Ok(s)=>{report.restore_readback_confirmed=restore_ok&&backlight_frame_matches(&s,saved,saved.observed_state[2]);report.restored_snapshot=Some(s);},Err(e)=>report.errors.push(("restored_read",e)),}
    report.outcome=if !report.restore_readback_confirmed{Outcome::RestoreUnconfirmed}else if trial_ok&&report.color_readback_confirmed&&report.errors.is_empty(){Outcome::ReadbacksConfirmed}else{Outcome::Failed};let message=if report.success(){"Four static target colors confirmed at brightness20; all original zones and normalized frame restored"}else if report.restore_readback_confirmed{"Static color trial failed; original four zones and frame confirmed"}else{"Original four-zone/frame restoration remains unconfirmed; inspect every restore write"};report.finish(message)
}
#[cfg(test)]mod tests{
    use super::*;use acer_protocol::{zone_color_word,ErrorKind,RawRead,RawValue};use std::collections::{VecDeque,BTreeMap};
    fn snapshot(target:bool)->Snapshot{let mut s:Snapshot=serde_json::from_str(include_str!("../../../crates/acer-protocol/tests/fixtures/phn16-71-elevated-read.json")).unwrap();if target{for r in &mut s.reads{if r.method=="GetGamingKBBacklight"{if let Some(RawValue::Bytes(b))=r.output.get_mut("gmOutput"){b[2]=20;}}if r.method=="GetGamingRgbKb"{let selector=r.input["gmInput"].as_u64().unwrap();let i=[1,2,4,8].iter().position(|v|*v==selector).unwrap();r.output.insert("gmOutput".into(),RawValue::unsigned(zone_color_word(i,VALIDATION_STATIC_ZONES[i]).unwrap()&!255));}}}s}
    fn applied(trial:bool)->ApplyReport{let saved=observed_backlight_frame(&snapshot(false)).unwrap();let calls=if trial{static_color_trial_plan(&saved).unwrap()}else{static_color_restore_plan(&saved).unwrap()};ApplyReport{status:ApplyStatus::Unconfirmed,message:"fake".into(),before:Some(snapshot(false)),after:None,writes:calls.into_iter().map(|c|RawRead{class:c.class,method:c.method,input:c.input,output:BTreeMap::from([("gmOutput".into(),RawValue::unsigned(0))]),error:None}).collect()}}
    fn error()->DeviceError{DeviceError{kind:ErrorKind::Transport,message:"fake failure".into()}}
    struct Fake{reads:VecDeque<Result<Snapshot,DeviceError>>,trial:Option<Result<ApplyReport,DeviceError>>,restore:Option<Result<ApplyReport,DeviceError>>,calls:Vec<&'static str>}
    impl Fake{fn new()->Self{Self{reads:[Ok(snapshot(false)),Ok(snapshot(true)),Ok(snapshot(false))].into(),trial:Some(Ok(applied(true))),restore:Some(Ok(applied(false))),calls:vec![]}}}
    impl ColorDevice for Fake{fn capabilities(&mut self)->Result<Capabilities,DeviceError>{Ok(Capabilities{model:"PHN16-71".into(),bios:"V1.18".into(),matched_model:true,items:vec![]})}fn snapshot(&mut self)->Result<Snapshot,DeviceError>{self.calls.push("read");self.reads.pop_front().unwrap()}fn colors(&mut self)->Result<ApplyReport,DeviceError>{self.calls.push("colors");self.trial.take().unwrap()}fn restore(&mut self)->Result<ApplyReport,DeviceError>{self.calls.push("restore");self.restore.take().unwrap()}fn settle(&mut self){self.calls.push("settle");}}
    #[test]fn target_colors_and_full_original_state_are_confirmed(){let mut f=Fake::new();assert!(validate(&mut f).success());assert_eq!(f.calls,["read","colors","settle","read","restore","read"]);}
    #[test]fn partial_trial_failure_still_restores_all_originals(){let mut f=Fake::new();let trial=f.trial.as_mut().unwrap().as_mut().unwrap();trial.status=ApplyStatus::Failed;trial.writes.truncate(2);f.reads.remove(1);let r=validate(&mut f);assert_eq!(r.outcome,Outcome::Failed);assert!(r.restore_attempted&&r.restore_readback_confirmed);assert_eq!(r.restore_apply.unwrap().writes.len(),5);}
    #[test]fn failed_color_read_still_restores(){let mut f=Fake::new();f.reads[1]=Err(error());let r=validate(&mut f);assert_eq!(r.outcome,Outcome::Failed);assert!(r.restore_readback_confirmed);}
    #[test]fn wrong_zone_is_not_a_successful_trial(){let mut f=Fake::new();f.reads[1].as_mut().unwrap().reads.iter_mut().find(|r|r.method=="GetGamingRgbKb").unwrap().output.insert("gmOutput".into(),RawValue::unsigned(0));let r=validate(&mut f);assert_eq!(r.outcome,Outcome::Failed);assert!(r.restore_readback_confirmed);}
    #[test]fn failed_restore_is_explicit(){let mut f=Fake::new();f.restore=Some(Err(error()));let r=validate(&mut f);assert_eq!(r.outcome,Outcome::RestoreUnconfirmed);assert!(r.restore_attempted);}
    #[test]fn nonstatic_original_refuses(){let mut f=Fake::new();if let Some(RawValue::Bytes(b))=f.reads[0].as_mut().unwrap().reads.iter_mut().find(|r|r.method=="GetGamingKBBacklight").unwrap().output.get_mut("gmOutput"){b[0]=3;}assert_eq!(validate(&mut f).outcome,Outcome::Rejected);assert_eq!(f.calls,["read"]);}
}
